  "screen.35ee85ea46d7": "Compare suas leituras",
  "screen.81c9b115fa7e": "Selecione até cinco artigos deste recorte para comparar suas anotações. As interpretações são suas; confira os resultados no artigo.",
  "screen.dbb242947ed8": "Anotações do usuário; campos em edição estão indicados como não salvos.",
  "screen.4bcdf1df1301": "neste recorte",
  "screen.cc9f3b6a13a0": "Pasta:",
  "screen.81a58b53b05b": "As sugestões abaixo vêm de regras aplicadas ao resumo; os campos editáveis são suas anotações e interpretações. A pré-análise usa apenas o abstract e o tipo de publicação. Ela ajuda a organizar a leitura, mas não substitui a leitura crítica do artigo completo. Confirme cada sugestão antes de incorporar.",
