  "screen.87139477eaaf": "Checklist editorial",
  "screen.44c80d2c947a": "O DOCX reúne o texto, as referências citadas e os resultados salvos disponíveis para sua conta. Salve tabelas e gráficos em Resultados antes de exportar. Confira as normas do periódico.",
