  "screen.af01f0eb81ef": "Carregar esta versão",
  "screen.63ac8294d01d": "Crie uma versão antes de uma revisão importante.",
  "screen.d561e47e1b89": "por um milhão de tokens. Nenhum consumo real de IA ocorre agora.",
  "screen.70b36b066b87": "Vagas configuráveis, turmas, convites e acompanhamento. A referência comercial é R$ 480 por vaga por ano, com franquia planejada de três milhões de tokens por vaga. O orçamento e as condições serão confirmados com cada programa.",
  "screen.806b587ca00d": "Conhecer o modelo institucional →",
  "screen.8b4a1c9a419d": "Os valores são uma proposta em validação, não uma oferta de assinatura ativa.",
  "screen.770beb0d8461": "Cancelamento",
  "screen.a6f04fc4cc1e": "Termos de uso",
  "screen.914c57e3c35e": "Aviso de privacidade.",
  "screen.95ea9df103cf": "Sua pergunta encontra a literatura.",
  "screen.7710de37ea9d": "Pesquise em português ou inglês. O Radar organiza conceitos, sinônimos e MeSH e prioriza os artigos mais relevantes.",
  "screen.b4f5d5c89107": "O que você gostaria de pesquisar?",
  "screen.a308f65e4139": "A estratégia separa conceitos, combina sinônimos com OR, conceitos com AND e acrescenta MeSH quando disponível. Até três buscas concluídas por dia; uma confirmação terminológica não consome tentativa.",
  "screen.b40964604a2d": "Um conceito ainda precisa de tradução biomédica.",
  "screen.a2523aa828cc": "A busca não foi enviada ao PubMed e não consumiu uma tentativa. Confirme o equivalente em inglês.",
  "screen.8cb3525e3b7e": "Criar conta",
  "screen.7a11604677d3": "A busca pode levar alguns segundos. Estamos consultando as bases científicas.",
  "screen.3c459fb25c4e": "Última consulta às bases:",
  "screen.1927150898a4": "tentativas restantes hoje",
