  "screen.8625880fb961": "Como interpretar os resultados",
  "screen.ca8a813a7b6c": "Da busca ao seu projeto.",
  "screen.6548bc7866d8": "Crie seu espaço para continuar a busca, selecionar referências, registrar a leitura e estruturar o protocolo. O tema poderá ser retomado neste navegador após o cadastro.",
