  "screen.3d764ea18b22": "Experimentar o Radar",
  "screen.991f80d4356d": "Como funciona",
  "screen.8244c69d2b60": "Analisando o artigo com IA",
  "screen.c933224a4889": "A IA está lendo o resumo disponível e preparando sugestões de campos com trechos de suporte. Você revisará as sugestões antes de salvar.",
  "screen.c631eafdd43c": "Encontramos",
