  "screen.a99bc3a53615": "conf.",
  "screen.ab37831d29bf": "Confirmar e incorporar",
  "screen.ba9a5c59bffa": "Confirme uma sugestão ou registre após a leitura...",
  "screen.df24cbf1e2d5": "Cancelamento e encerramento de conta.",
  "screen.cb1c62425647": "Uma boa pesquisa ganha forma, etapa por etapa.",
  "screen.6bd96d610c0d": "Comece pelo ponto em que você está. O Scholar organiza as decisões e a literatura para a conversa com seu orientador.",
  "screen.82ade609b978": "O que você leva desta etapa",
  "screen.00d551e63dd5": "Perfil",
  "screen.dc65a571504f": "registros",
  "screen.87aebd06e85c": "Acrescentar informação",
  "screen.e1d12d1a29a7": "Enviar",
  "screen.9579e70abb6f": "para confirmar",
  "screen.e718868c0fd7": "Vamos entender o que você precisa.",
  "screen.3a0ca3927238": "Envie dúvidas, sugestões ou conte como sua residência pretende desenvolver a produção científica.",
  "screen.4e1a3b797aea": "Dúvida ou suporte",
  "screen.85b5eb354c28": "Privacidade e dados",
  "screen.0f7f8fb6b574": "Sugestão ou outro assunto",
  "screen.e3766572e07e": "Usamos estes dados para atender sua solicitação, conforme a",
  "screen.adbdf7656ea0": "política de privacidade",
  "screen.69cf859c2eac": "Uma conversa com direção",
  "screen.3d38481b4af3": "Como podemos ajudar?",
  "screen.eea735f83436": "Para um piloto institucional, informe o programa, o número de residentes e as necessidades da coordenação. Para suporte, descreva a página e o que ocorreu.",
  "screen.f722a391f0de": "Solicitações sobre seus dados",
  "screen.0acad4615f1d": "Escolha Privacidade e dados. Podemos orientar sobre acesso, correção ou exclusão da conta.",
  "screen.60e8a4296ade": "O que não enviar",
  "screen.7c525251d4d7": "Evite informações de pacientes, dados sensíveis, senhas, cartões ou dados bancários.",
  "screen.7d6afda319e8": "A mensagem é registrada para a equipe. Nesta etapa não há confirmação automática por e-mail.",
  "screen.2c1aafb83914": "Carregando opções de contratação...",
  "screen.083cff630878": "Entre para escolher sua licença.",
  "screen.1fdff273ce1e": "Entrar na conta",
  "screen.2ac304df498c": "Contratação e recargas",
  "screen.ad4371fc3ee5": "Prepare sua licença anual.",
  "screen.833d0b11906a": "Escolha o plano, a forma de pagamento desejada e, para residências, a quantidade exata de vagas. Nesta fase a solicitação é registrada, mas não abre checkout nem gera cobrança.",
  "screen.2ce2bd5e2c82": "Nenhum cartão será solicitado e nenhuma licença paga será ativada automaticamente.",
  "screen.0ca6dc7b69d6": "Nova solicitação",
  "screen.94f633413108": "Tipo de licença",
  "screen.010dd7b94f5f": "Individual",
  "screen.dc953d4ca934": "Programa de residência",
  "screen.6c55806376ab": "Plano",
  "screen.957bc40226f7": "Condição desejada",
  "screen.9d4f11e25866": "Pagamento anual",
  "screen.4d43a6558c98": "Licença anual em 12 parcelas",
  "screen.33ad4aad4288": "Quantidade de vagas",
  "screen.8f92935483c2": "Nome do programa ou instituição",
  "screen.f24b447bf58e": "Ex.: Residência de Clínica Médica",
  "screen.0145d934eb76": "Cupom de teste ou condição especial",
  "screen.a6e63474985f": "Opcional",
  "screen.920c48e9ba3e": "Licença anual",
  "screen.9dea6203ae5a": "Franquia planejada",
  "screen.21003e165b48": "O valor final e eventual desconto são recalculados com segurança no servidor ao registrar a solicitação.",
  "screen.327262d14c89": "Recarga opcional",
  "screen.b5cacf9e1de6": "Cada pacote adicionará 1 milhão de tokens e será válido até o fim da licença escolhida.",
  "screen.70dfbb512f68": "Licença",
  "screen.3cbfc4850066": "Pacotes",
