  "screen.e5c04cf94e21": "Falhas também ocupam o envelope financeiro diário; a franquia de tokens é devolvida quando a operação falha. A ativação exige tarifas reais e instalação do SQL. Este diagnóstico não liga a IA nem altera limites.",
