  "screen.e16c1a5f85bc": "Um lugar para construir seu raciocínio científico.",
  "screen.8f10f5a46373": "Estamos em fase de testes. A assistência por IA e a contratação com pagamento serão ativadas em uma próxima etapa. As ideias atuais usam regras e os dados do Radar vêm de bases científicas.",
