  "screen.474723b300c5": "Confirme a especificação, a independência e a revisão dos pressupostos e resíduos antes de apresentar a inferência.",
  "screen.da4b5119bdaa": "Regressão linear por mínimos quadrados, com intercepto, uma observação inicial por participante e casos completos em todas as variáveis escolhidas. Os coeficientes numéricos representam diferença no desfecho por 1 unidade do ajuste; os categóricos, diferença em relação à referência, mantendo os demais ajustes constantes. Erros-padrão clássicos, IC95% e p bilateral pela distribuição t: exigem revisão de linearidade, independência entre participantes, homoscedasticidade, normalidade aproximada dos resíduos para inferência e observações influentes. Os limiares de Cook (4/N) e alavancagem (2p/N) são sinais de conferência, não justificam exclusão automática. Não há seleção automática de confundidores, imputação, interações, inferência robusta, ajuste por multiplicidade, validação preditiva ou análise longitudinal nesta etapa. Associação ajustada não demonstra causalidade; viés por perdas e confundimento residual podem permanecer.",
