  "screen.953b0bed1730": "A inferência excedeu a precisão numérica disponível. Confira os dados.",
  "screen.c7340d37253e": "ANOVA de medidas repetidas de um fator (momento), com correção de Greenhouse–Geisser aplicada sempre. Usa os mesmos participantes com dados completos em todos os momentos selecionados, vinculados pelo código, sem imputação. Perdas podem enviesar a análise. Exige escala comparável, independência entre participantes e adequação da normalidade dos contrastes/resíduos e dos valores extremos. A correção de esfericidade não corrige não normalidade, confundimento ou comparações múltiplas. O teste global não identifica quais momentos diferem, não modela intervalos reais entre consultas e não demonstra causalidade. Não há comparações pós-teste automáticas, modelos mistos ou ajuste por covariáveis nesta etapa.",
