  "screen.dbb242947ed8": "Notas del usuario; los campos en edición se indican como no guardados.",
  "screen.4bcdf1df1301": "en esta selección",
  "screen.cc9f3b6a13a0": "Carpeta:",
  "screen.81a58b53b05b": "Las sugerencias de abajo proceden de reglas aplicadas al resumen; los campos editables son tus notas e interpretaciones. El preanálisis utiliza solo el resumen y el tipo de publicación. Ayuda a organizar la lectura, pero no sustituye la lectura crítica del artículo completo. Confirma cada sugerencia antes de incorporarla.",
