  "screen.9fb9c79e632c": "No hay tareas pendientes abiertas.",
  "screen.87139477eaaf": "Lista de revisión editorial",
  "screen.44c80d2c947a": "El DOCX reúne el texto, las referencias citadas y los resultados guardados disponibles para tu cuenta. Guarda las tablas y los gráficos en Resultados antes de exportar. Consulta las normas de la revista.",
  "screen.e7e4a84eeafa": "Versiones",
  "screen.d7dbc9c5f24f": "Borrador",
  "screen.5f8054983449": "En revisión",
  "screen.039eb59231cc": "Listo",
  "screen.ddd42a7d3ec6": "Enviado",
  "screen.553b8691d3f4": "Selecciona dos versiones para compararlas en paralelo.",
  "screen.af01f0eb81ef": "Cargar esta versión",
  "screen.63ac8294d01d": "Crea una versión antes de una revisión importante.",
  "screen.d561e47e1b89": "por un millón de tokens. No se produce ningún consumo real de IA ahora.",
  "screen.70b36b066b87": "Plazas configurables, cohortes, invitaciones y seguimiento. La referencia comercial es R$ 480 por plaza al año, con una cuota prevista de tres millones de tokens por plaza. El presupuesto y las condiciones se confirmarán con cada programa.",
  "screen.806b587ca00d": "Conocer el modelo institucional →",
  "screen.8b4a1c9a419d": "Los importes son una propuesta en validación, no una oferta de suscripción activa.",
  "screen.770beb0d8461": "Cancelación",
  "screen.a6f04fc4cc1e": "Términos de uso",
  "screen.914c57e3c35e": "Aviso de privacidad.",
  "screen.95ea9df103cf": "Tu pregunta encuentra la literatura.",
  "screen.7710de37ea9d": "Busca en portugués o inglés. Radar organiza conceptos, sinónimos y MeSH y prioriza los artículos más relevantes.",
  "screen.b4f5d5c89107": "¿Qué te gustaría investigar?",
  "screen.a308f65e4139": "La estrategia separa conceptos, combina sinónimos con OR y conceptos con AND, y añade MeSH cuando está disponible. Hasta tres búsquedas completadas al día; una confirmación terminológica no consume un intento.",
  "screen.b40964604a2d": "Un concepto aún necesita traducción biomédica.",
  "screen.a2523aa828cc": "La búsqueda no se envió a PubMed y no consumió un intento. Confirma el equivalente en inglés.",
  "screen.8cb3525e3b7e": "Crear cuenta",
  "screen.7a11604677d3": "La búsqueda puede tardar unos segundos. Estamos consultando las bases científicas.",
  "screen.3c459fb25c4e": "Última consulta a las bases:",
  "screen.1927150898a4": "intentos restantes hoy",
  "screen.99475d77a750": "Cómo interpretó Radar",
