  "screen.238300f5844a": "Leer resumen",
  "screen.c84298224bce": "Consultar en PubMed",
  "screen.69a87f9c8fad": "No hay artículos con detalles disponibles en esta selección. Prueba términos más específicos o sinónimos.",
  "screen.8625880fb961": "Cómo interpretar los resultados",
  "screen.ca8a813a7b6c": "De la búsqueda a tu proyecto.",
  "screen.6548bc7866d8": "Crea tu espacio para continuar la búsqueda, seleccionar referencias, registrar la lectura y estructurar el protocolo. Podrás retomar el tema en este navegador después del registro.",
