  "screen.97a22baba698": "Programas de residencia",
  "screen.676f85d53760": "Residentes y coordinación",
  "screen.659df193143d": "Cada residente usa su propia cuenta. La coordinación consulta los proyectos compartidos con el programa; las ideas y la biblioteca personales permanecen privadas.",
  "screen.eef50af05224": "Mi licencia y cuota",
