  "screen.99ffd700ce1e": "plazas ·",
  "screen.f28ea827611f": "tokens ·",
  "screen.1af132f76cb9": "· hasta",
  "screen.0ddd49b2c67b": "Estás vinculado como residente. Para compartir un trabajo, guárdalo en Mi proyecto y elige el programa en la sección de uso compartido.",
