  "screen.40cb5880d808": "Sin cohorte",
  "screen.1bb5fcc5bc2a": "Usos del código",
  "screen.db1a58951a67": "Generar código · hasta 7 días",
  "screen.ab2878ceb453": "Código para copiar",
  "screen.300ecdcb3a4c": "Residentes ·",
  "screen.7944041c8885": "plazas",
  "screen.f5693728450c": "La redistribución no puede reducir el saldo por debajo del consumo y de las reservas. El total no supera la cuota institucional.",
  "screen.bf2949a5cfa2": "tokens utilizados ·",
  "screen.80ddf0b21bd9": "reservados",
