  "screen.cbb6649f3f5c": "Antes:",
  "screen.316c5be50cad": "Antes ·",
  "screen.c925892e07ed": "Contexto y citas",
  "screen.e9daca354ed6": "Objetivo",
  "screen.a92de2d80938": "Revisar protocolo →",
  "screen.8825cf951da1": "Vancouver",
  "screen.c9f3cbd5d37a": "ABNT",
  "screen.24ac9492265f": "Abrir Biblioteca →",
  "screen.7f6875a665a3": "Antes de exportar",
  "screen.5d59984ea0ab": "Integración de resultados",
  "screen.ef080721af4a": "Resultados en el manuscrito",
  "screen.08951a92de53": "A la espera de revisar los resultados guardados.",
  "screen.ed72576c3d34": "Los datos o análisis cambiaron desde la última transferencia. Revisa la sección Resultados antes de exportar.",
  "screen.181c5999ac87": "Revisar actualización",
  "screen.27a946e5429a": "Vista previa recibida de Resultados. El texto se añadirá al final de la sección, conservando el contenido actual y creando una versión anterior.",
  "screen.607b5dd2c3eb": "Texto por añadir",
  "screen.0752c9df81d0": "La base guardada cambió. Vuelve a Resultados y prepara una nueva vista previa.",
  "screen.eade13b2fd02": "Descartar vista previa",
  "screen.7175febeb709": "La IA está revisando esta sección con el protocolo y las fuentes seleccionadas. La sugerencia estará disponible para comparar antes de aplicarla.",
  "screen.8de07912cb8e": "Estructurar sección",
  "screen.211b7a03fa3f": "Revisar coherencia científica",
  "screen.4a81b1c536a1": "Mejorar claridad y redacción",
  "screen.ff062c6f63ab": "Elegir fuentes del proyecto · hasta 5",
  "screen.984402d0ed3e": "Vincula artículos en la biblioteca para usar literatura como contexto.",
  "screen.eb436b89e5a9": "Hasta 10.000 tokens por operación. Se enviarán el protocolo y las fuentes seleccionadas para análisis. La sección debe tener hasta 12.000 caracteres y se enviará completa.",
  "screen.14127fbe5557": "Ver registro de este intento",
  "screen.02ec9e76fdd7": "Original analizado",
  "screen.a8675ebbcce4": "Sugerencia · puedes editarla",
  "screen.5fd67cd732e8": "Justificaciones y fuentes utilizadas",
  "screen.0dd6da8d793f": "Fuente:",
  "screen.6458b37d4a4f": ". Tiempo de respuesta:",
  "screen.382584f2456e": "s.",
  "screen.aa160596aada": "Conservar versión y aplicar",
  "screen.1a878a55c594": "Descartar",
  "screen.27db94b3f7a3": "Registro, consumo y evaluación",
  "screen.c21492af5260": "El texto actual cambió. Realiza un nuevo análisis antes de aplicarlo.",
  "screen.98175b59809b": "Proyecto eliminado. Actualizando la lista…",
  "screen.ba218a735137": "Eliminar proyecto",
  "screen.c5212932c855": "¿Eliminar este proyecto?",
  "screen.f2dc752c7d8b": "Esta acción es permanente. Se eliminarán el protocolo, el manuscrito y sus versiones, los resultados, el recorrido y los registros de tutoría vinculados. Se cerrarán los accesos compartidos. Se conservarán los artículos y evaluaciones de la biblioteca, así como las ideas guardadas.",
  "screen.f68a9f94d9bc": "Escribe EXCLUIR para confirmar",
  "screen.04be19f79e2e": "Seguimiento del proyecto",
  "screen.8979984026f0": "Próximo paso",
  "screen.e464408181fe": "Guardar proyecto para continuar",
  "screen.2e26f24d9de9": "Próximo plazo:",
  "screen.4785d7b832f4": "Referencias vinculadas:",
  "screen.3b93719e2ff8": "· Estrategias guardadas:",
  "screen.671fd3460040": "· Manuscrito:",
  "screen.97f9b8a74112": "Revisar mi proyecto · opcional",
  "screen.1b7b6c0b9dea": "Los registros de tema, pregunta, método, referencias y redacción se reconocen automáticamente. No demuestran calidad científica ni ejecución. Confirma la ética, recopilación, análisis y entrega cuando ocurran.",
  "screen.04d846d589f1": "Revisar la estructura del protocolo",
  "screen.62157a840f2c": "Las verificaciones por reglas de campos no sustituyen la revisión científica ni la del tutor.",
  "screen.c2adc246808d": "Revisión y seguimiento opcionales",
  "screen.69917df6e25f": "Marca anterior conservada:",
