  "screen.f06c4826ca03": "Confirmada",
  "screen.0fff1ccde9ea": "Bloqueada",
  "screen.f8fb5c44fe19": "Plazo (opcional)",
  "screen.2a5c9c5b2c17": "Tarea pendiente o nota",
  "screen.c94baf60298f": "Registra solo lo que necesitas seguir",
  "screen.c048f30b9bf3": "Quitar bloqueo anterior",
  "screen.38db67686408": "Guarda el proyecto antes de registrar confirmaciones y plazos.",
  "screen.787170dd236e": "Cargando seguimiento…",
  "screen.bdcf7b5d8ed7": "Hay cambios en este trabajo",
  "screen.95d0635682a9": "Guarda antes de salir para conservar los cambios en tu cuenta. Si los descartas, solo estará disponible la versión ya guardada.",
  "screen.a226aabb5545": "Continuar editando",
  "screen.a43f41017e74": "Descartar y salir",
  "screen.a522f5a6dd79": "Elegir proyecto de trabajo",
  "screen.cc11df91e214": "Tus proyectos",
  "screen.8944ff85e734": "Proyecto en edición",
  "screen.7983bf7895e9": "+ Nuevo proyecto",
  "screen.f1e8688b77de": "Hay cambios sin guardar en este proyecto.",
  "screen.a16e52b9cc6d": "Guardar antes de cambiar",
  "screen.68b44d6183ea": "Plan de trabajo del proyecto",
  "screen.5d727611d21e": "Transforma las orientaciones en tareas. Tú confirmas su finalización; completar campos o terminar una tarea no valida la calidad científica.",
  "screen.9ed78a00a260": "abiertas ·",
  "screen.8de71b4b82b4": "completadas",
