  "screen.3150dcf6f9b0": "GRUPOFUNDADOR",
  "screen.bb9dbb406dcb": "Cancelar",
  "screen.7ae9d418353b": "Idioma",
  "screen.40e49271ddad": "Operaciones",
  "screen.da53c8aaf6fe": "Conoce Scholar",
  "screen.86202fa087ac": "Ayuda e información",
  "screen.6f85c169ecd0": "Mi espacio",
  "screen.1812f6cfbce8": "Mi proyecto",
  "screen.5a4cc65d866b": "Cuenta",
  "screen.3d764ea18b22": "Probar Radar",
  "screen.991f80d4356d": "Cómo funciona",
  "screen.8244c69d2b60": "Analizando el artículo con IA",
  "screen.c933224a4889": "La IA está leyendo el resumen disponible y preparando sugerencias de campos con fragmentos de respaldo. Revisarás las sugerencias antes de guardar.",
  "screen.c631eafdd43c": "Encontramos",
  "screen.6c64535dc57d": "Filtrar biblioteca por proyecto",
  "screen.580cfe248b0c": "Artículos para el asistente",
  "screen.52fadddb772f": "Revisar",
  "screen.45789cc13c6b": "Campo",
  "screen.808630f5f236": "Comparar evidencias con IA",
  "screen.d0692b943f01": "Sintetiza coincidencias, diferencias, limitaciones y brechas solo a partir de los artículos y notas seleccionados.",
  "screen.b3a272ef4dce": "Lista de artículos",
  "screen.898f58475284": "Detalles del artículo seleccionado",
  "screen.b8f1005e1462": "Modelo:",
