  "screen.09828b0f7eef": "Población / muestra",
  "screen.4d04250d354e": "Hallazgo principal",
  "screen.d996a84e2773": "Tamaño de la muestra",
  "screen.98d29d7d4048": "Intervención / exposición",
  "screen.ff35cce556be": "Comparador",
