  "screen.5ac5133cf16f": "Notas generales de lectura",
  "screen.798a730ad8d0": "Ej.: Fundamentación teórica",
  "screen.c4e05782dbd7": "adherencia, residentes, revisión",
  "screen.e7a2c0c4dbfb": "Favorito",
  "screen.a99bc3a53615": "conf.",
  "screen.ab37831d29bf": "Confirmar e incorporar",
  "screen.ba9a5c59bffa": "Confirma una sugerencia o registra tus notas después de leer...",
  "screen.df24cbf1e2d5": "Cancelación y cierre de cuenta.",
  "screen.cb1c62425647": "Una buena investigación toma forma, etapa por etapa.",
  "screen.6bd96d610c0d": "Empieza desde donde estés. Scholar organiza las decisiones y la literatura para la conversación con tu tutor.",
  "screen.82ade609b978": "Qué obtienes en esta etapa",
  "screen.00d551e63dd5": "Perfil",
  "screen.dc65a571504f": "registros",
  "screen.87aebd06e85c": "Añadir información",
  "screen.e1d12d1a29a7": "Enviar",
  "screen.9579e70abb6f": "para confirmar",
  "screen.e718868c0fd7": "Vamos a entender qué necesitas.",
  "screen.3a0ca3927238": "Envía dudas, sugerencias o cuéntanos cómo tu programa de residencia quiere desarrollar la producción científica.",
  "screen.4e1a3b797aea": "Duda o soporte",
  "screen.85b5eb354c28": "Privacidad y datos",
  "screen.0f7f8fb6b574": "Sugerencia u otro asunto",
  "screen.e3766572e07e": "Usamos estos datos para atender tu solicitud, según la",
  "screen.adbdf7656ea0": "política de privacidad",
  "screen.69cf859c2eac": "Una conversación con dirección",
  "screen.3d38481b4af3": "¿Cómo podemos ayudar?",
  "screen.eea735f83436": "Para un piloto institucional, indica el programa, el número de residentes y las necesidades de coordinación. Para soporte, describe la página y lo ocurrido.",
  "screen.f722a391f0de": "Solicitudes sobre tus datos",
  "screen.0acad4615f1d": "Elige Privacidad y datos. Podemos orientarte sobre el acceso, la corrección o la eliminación de la cuenta.",
  "screen.60e8a4296ade": "Qué no enviar",
  "screen.7c525251d4d7": "Evita información de pacientes, datos sensibles, contraseñas, tarjetas o datos bancarios.",
