  "screen.9a812dad1fc0": "Esta reserva se ajusta al consumo confirmado al terminar la operación; un fallo confirmado libera los tokens. Límite de",
  "screen.851d991587ca": "intentos diarios, con reinicio a medianoche UTC (21 h en Brasilia). Las recargas aumentan la cuota sin cambiar ese límite diario ni la vigencia de la licencia.",
