  "screen.b0ccf352d684": "· por licencia:",
  "screen.e5c04cf94e21": "Los fallos también ocupan la reserva financiera diaria; la cuota de tokens se devuelve cuando la operación falla. La activación requiere tarifas reales e instalación del SQL. Este diagnóstico no activa la IA ni modifica los límites.",
