  "screen.c0286bd223ed": "La configuración no demuestra la entrega. Valida una alerta en una búsqueda de prueba antes de habilitar el envío a los residentes.",
  "screen.839cd6a7e1c1": "Casos de evaluación científica",
  "screen.fc687ef951f4": "Usa estos escenarios en las funciones existentes y evalúa la respuesta en Detalles de la generación. No hay llamadas automáticas ni costos en esta página.",
