  "screen.2e534b4eca32": "Organiza tu trabajo de fin de estudios, artículo o proyecto de residencia. Compara caminos y desarrolla la pregunta, los objetivos, los criterios y los métodos a tu ritmo.",
  "screen.256da5920d8e": "Crear mi espacio de investigación →",
