  "screen.2ac4c9724d46": "Decisiones organizadas para discutir con el tutor.",
  "screen.e2f072287a52": "Registra el razonamiento del proyecto y exporta la estructura del protocolo para revisión. Un recorrido individual que puede apoyar el desarrollo académico de los residentes.",
  "screen.eab3fde3dc09": "Conocer el acceso institucional →",
  "screen.83a388d53f29": "Herramientas disponibles",
  "screen.e16c1a5f85bc": "Un lugar para construir tu razonamiento científico.",
  "screen.8f10f5a46373": "Estamos en fase de prueba. La asistencia por IA y la contratación con pago se activarán en una próxima etapa. Las ideas actuales utilizan reglas y los datos de Radar proceden de bases científicas.",
  "screen.bdf3e4eb4374": "Conocer el recorrido completo →",
