  "screen.eb70eee6631b": "Prueba con un tema real de tu área.",
  "screen.8ceaf1205b22": "Explora tu área, encuentra una pregunta viable y reúne las decisiones del protocolo en un solo lugar. La literatura y la orientación científica acompañan ese recorrido.",
  "screen.c76a31c9cee3": "Abrir Radar",
  "screen.c1a683a7fd3a": "Cada residente con su proyecto. La coordinación con una visión del recorrido.",
  "screen.e2867b5b6ecd": "Organiza la participación del programa y consulta los trabajos compartidos, preservando el espacio individual de investigación.",
  "screen.d21769aca8f3": "Conversar sobre un piloto ↗",
  "screen.e99391cade24": "De la invitación al seguimiento",
  "screen.5eec9fc60bbc": "Un programa organizado para avanzar juntos.",
  "screen.fd6f9fb2f664": "Define las plazas, organiza las cohortes e invita a los residentes. Cada participante trabaja en su cuenta y elige qué proyectos compartir.",
