  "screen.5beab0207d3b": "Los diagnósticos superan la precisión numérica disponible.",
  "screen.69cee9892e4d": "El resumen del ajuste supera la precisión numérica.",
  "screen.474723b300c5": "Confirma la especificación, la independencia y la revisión de los supuestos y residuos antes de presentar la inferencia.",
  "screen.da4b5119bdaa": "Regresión lineal por mínimos cuadrados, con intercepto, una observación inicial por participante y casos completos en todas las variables elegidas. Los coeficientes numéricos representan la diferencia en el desenlace por 1 unidad del ajuste; los categóricos, la diferencia respecto de la referencia, manteniendo constantes los demás ajustes. Errores estándar clásicos, IC95% y p bilateral por la distribución t: requieren revisar linealidad, independencia entre participantes, homocedasticidad, normalidad aproximada de los residuos para la inferencia y observaciones influyentes. Los umbrales de Cook (4/N) y apalancamiento (2p/N) son señales de revisión, no justifican una exclusión automática. No hay selección automática de factores de confusión, imputación, interacciones, inferencia robusta, ajuste por multiplicidad, validación predictiva ni análisis longitudinal en esta etapa. Una asociación ajustada no demuestra causalidad; pueden persistir el sesgo por pérdidas y la confusión residual.",
