  "screen.c7340d37253e": "ANOVA de medidas repetidas de un factor (momento), con corrección de Greenhouse–Geisser aplicada siempre. Usa los mismos participantes con datos completos en todos los momentos seleccionados, vinculados por el código, sin imputación. Las pérdidas pueden sesgar el análisis. Requiere una escala comparable, independencia entre participantes y adecuación de la normalidad de los contrastes/residuos y de los valores extremos. La corrección de esfericidad no corrige la falta de normalidad, la confusión ni las comparaciones múltiples. La prueba global no identifica qué momentos difieren, no modela los intervalos reales entre consultas ni demuestra causalidad. No hay comparaciones posteriores automáticas, modelos mixtos ni ajuste por covariables en esta etapa.",
