  "Ajustado:": "screen.c159e832852a",
  "Resíduo: ±": "screen.c92d7cdf68c8",
  "Resíduo é a diferença entre o valor observado e o estimado pelo modelo. Procure curvatura, formato de funil e pontos isolados; o gráfico não verifica os pressupostos automaticamente. Não use R² como validação de previsão clínica.": "screen.d2ffa6751977",
  "Dados próprios · primeira análise multivariável": "screen.c6fe07d4199a",
  "Considerar outras características": "screen.2a001fa43074",
  "Analise um desfecho numérico da ficha inicial considerando até três características dos participantes. Esta etapa usa uma observação por participante incluído, sem os filtros da agenda ou da comparação entre grupos. As visitas não são tratadas como linhas independentes.": "screen.1fea419b0950",
  "Defina um desfecho numérico na ficha inicial para preparar este modelo.": "screen.a7c643e02211",
  "Qual medida você quer estudar?": "screen.fbea4034742d",
  "Quais outras características serão consideradas? · até três": "screen.16fd5b30850d",
  "Exemplo: estudar pressão arterial considerando idade e grupo de tratamento. Escolha as características previstas no protocolo, antes de avaliar os valores de p. Datas não entram nesta versão; variáveis categóricas aceitam duas a quatro opções e exigem referência escolhida. Códigos numéricos definidos como categorias continuam categóricos.": "screen.878996b1862c",
  "Grupo usado como base da comparação de": "screen.ea5f4fa4e322",
  "Escolha a referência": "screen.f294e9136ee4",
  "Conferir minha análise": "screen.319074de070f",
  "Os resultados abaixo correspondem ao modelo aplicado. Alterações nos campos acima só entram ao clicar em Conferir minha análise. Salvar resultados guarda o modelo na conta.": "screen.e99f9823b1a0",
  "Desfecho:": "screen.ae0a6f3dd665",
  "participantes completos de": "screen.4574a743be44",
  "incluídos;": "screen.842eb12ff1a2",
  "fora por dados ausentes. O modelo inclui": "screen.9559abf6f8e8",
  "coeficientes, contando o intercepto.": "screen.eb3c7f973479",
  "Conferir variáveis e dados ausentes": "screen.9ddd7c4c90b6",
  "As ausências por variável podem se sobrepor. Na seleção, primeiro são contados desfechos vazios; depois ajustes vazios entre os que têm desfecho. Não há imputação nem exclusão automática por influência.": "screen.21f4126a4492",
  "sinais de influência (Cook &gt; 4/N) e": "screen.abaf206e1587",
  "de alavancagem (h &gt; 2p/N). São alertas para conferência, não motivos automáticos para remover participantes.": "screen.5cc3ae8295c6",
  "Conferir resíduos e observações por participante": "screen.d2dd46c8bff1",
  "Revise erros, escala, resíduos, influência e adequação da distribuição. Os códigos e valores individuais desta lista não entram nas exportações agregadas.": "screen.ddf0dd0b2c74",
  "Diagnósticos anteriores": "screen.d50c027c0933",
  "Página": "screen.8f63f4d7594a",
  "de": "screen.959a45d44e6f",
  "Próximos diagnósticos": "screen.5aa1b74977ac",
  "Regressão linear · estimativas ajustadas": "screen.e8dc5e811770",
  "Método e condições de uso": "screen.ac4ce58d70b7",
  "Os coeficientes estão na unidade original do desfecho. Para ajustes numéricos, representam diferença por 1 unidade; para categorias, diferença em relação à referência, mantendo os demais ajustes constantes. Erros-padrão clássicos, IC95% e p bilateral exigem revisão dos pressupostos. Não são estimativas causais nem previsões clínicas validadas.": "screen.f0ee43f05f24",
  "Limite operacional: pelo menos 20 participantes completos e cinco por coeficiente, incluindo o intercepto; isso não garante poder ou adequação. Modelos constantes, redundantes, numericamente instáveis ou sem variabilidade residual são bloqueados. Não há seleção automática de confundidores ou ajuste robusto nesta etapa.": "screen.8bcc02cb09f7",
  "Conferi a especificação e a escala, a independência entre participantes, a linearidade, a variância aproximadamente constante e a normalidade aproximada dos resíduos para inferência, além das observações influentes.": "screen.c0c9642c6c73",
  "Revise os resíduos e confirme os pressupostos para apresentar coeficientes, intervalos e valores de p.": "screen.ccbccd1c33fb",
  "Tabela completa de coeficientes e detalhes do ajuste": "screen.3bd1d7e85051",
  "Texto sugerido para revisão": "screen.42f197f5c1ee",
  "Limitações e informações do método": "screen.66b3d7d8e8b2",
  "Modelo ajustado em Excel": "screen.928602ce6003",
  "Modelo ajustado em Word": "screen.37ee6ec0d771",
  "Remover modelo ajustado": "screen.52e809b77331",
  "Estudos com dados próprios · primeira etapa": "screen.f89d7c581eb1",
  "Ficha dos participantes": "screen.c8663c0c9387",
  "Use códigos de pesquisa, como P001. Remova nomes, documentos, nascimento, contatos e números de prontuário antes de importar. A chave que liga o código à pessoa deve permanecer na instituição. Códigos não garantem anonimização; confirme as autorizações e exigências éticas do estudo. A IA desta ficha recebe somente o protocolo e as definições das variáveis.": "screen.c830789d2469",
  "Preparar ficha de coleta": "screen.3181f993200d",
  "Os critérios são trazidos do protocolo salvo. Você revisa as variáveis antes de iniciar a coleta.": "screen.5a27e413e22e",
