  "Ex.: atendimentos de janeiro a dezembro de 2025": "screen.98fb6b064aea",
  "As categorias, unidades, campos necessários e limites são decisões do protocolo. Limites numéricos servem para conferência; não são pontos de corte clínicos sugeridos pelo Scholar. Células vazias representam dados não registrados.": "screen.c4ae80e53bd7",
