  "Como ler esta tabela?": "screen.fd5ab2540f9a",
  "N é a quantidade de valores informados. Média é a soma dos valores dividida pela quantidade; mediana é o valor central quando eles são ordenados. DP (desvio-padrão) descreve a dispersão em torno da média. Nas categorias, n (%) mostra quantidade e percentual entre quem tem resposta informada; dados ausentes aparecem separados.": "screen.83c5ea044beb",
  "Somente os": "screen.457f71e11a41",
  "incluídos entram nos cálculos. Percentuais usam os valores informados de cada variável; ausências aparecem separadas. A ficha usa o tipo definido pelo pesquisador, inclusive para categorias codificadas com números. DP amostral; indisponível com um único valor.": "screen.5f120753108d",
  "Confira e inclua registros para gerar o perfil. Registros pendentes e excluídos não entram na tabela.": "screen.3d135777aea3",
  "Ao salvar os resultados, esta tabela acompanha as exportações Word do projeto e do manuscrito. As contagens descrevem a base coletada; não demonstram causalidade nem representatividade da população.": "screen.d26256d10901",
