  "A ordem de seleção define a apresentação dos grupos e o sentido da diferença de médias. Para trocar uma das duas categorias, adicione a nova antes de remover a anterior.": "screen.33f8c0f9c25a",
  "Ainda não há participantes incluídos nos grupos selecionados. Confira a coleta.": "screen.c5b30b43f951",
