  "Investigar uma diferença ou associação": "screen.bcefd8bed229",
  "Selecione uma variável por vez. Numérica: teste de Welch entre exatamente dois grupos. Categórica: qui-quadrado, sujeito às frequências esperadas. Datas não são testadas. Não há cálculo automático de p para todas as linhas da tabela.": "screen.db07d3ad8b8d",
  "Variável a investigar": "screen.f8ade4691f6c",
  "As observações devem ser independentes. Esta etapa não analisa antes/depois, medidas repetidas ou ajustes por confundidores.": "screen.1f45edc43940",
