  "Detalhes estatísticos da comparação": "screen.05725214a4b6",
  "Resultado exploratório sem correção para comparações múltiplas. Valor de p não mede importância clínica. Revise o resultado e sua interpretação antes de usá-los no manuscrito.": "screen.d42eb87b47ff",
