  "Visitas e medidas posteriores": "screen.103cbf53ef63",
  "Registre consultas, medidas, tratamentos e desfechos em diferentes momentos para a mesma pessoa. A ficha inicial e a comparação entre grupos continuam usando uma linha por participante. As visitas têm uma ficha própria e não entram como observações independentes nessas análises.": "screen.5c050148a406",
  "Use apenas códigos de pesquisa. Datas e dados de saúde exigem os mesmos cuidados e autorizações da coleta inicial. Nenhum dado de visita é enviado à IA por esta seção.": "screen.701b9ed00e2e",
  "Quando e o que será registrado?": "screen.96db29a6ecef",
  "Defina os momentos e o número de dias após a data de início de cada participante. Início, 30 e 90 dias são sugestões editáveis. Defina medidas conforme o protocolo, incluindo tratamentos ou desfechos como variáveis categóricas quando necessário.": "screen.795662fe9d85",
