  "Os resultados abaixo correspondem à seleção aplicada e salva neste espaço. Mudanças nos campos acima só entram ao clicar em Aplicar seleção. A inferência precisa de nova conferência após mudanças nos dados ou no plano.": "screen.9214fe1e6066",
