  "pares com datas reais invertidas. As contagens e os valores permanecem visíveis para conferência; o teste fica bloqueado. Revise as datas nas visitas.": "screen.96f86fd004dd",
  "Conferir diferenças por participante": "screen.fd3be976d834",
  "Revise a escala, a assimetria e os valores extremos das diferenças. Esta lista usa os pares completos e não é incluída no Word ou manuscrito.": "screen.4625eac17ae5",
  "Pares anteriores": "screen.af472c666f4d",
  "Próximos pares": "screen.7aabded26d29",
  "Teste t pareado · bilateral": "screen.80837524b59d",
  "O teste avalia se a mudança média difere de zero. Revise a distribuição das diferenças, sobretudo em amostras pequenas. Os participantes devem ser independentes entre si, e os valores de cada par devem pertencer à mesma pessoa, na mesma escala. Esta versão exige ao menos três pares completos; esse mínimo não garante adequação. Categorias, testes não paramétricos e três ou mais momentos não são analisados aqui.": "screen.6a307f3ed646",
  "Conferi o pareamento e a escala, a independência entre participantes, a normalidade aproximada das diferenças e os valores extremos.": "screen.839781a01610",
