  "Compare globalmente uma medida numérica nos mesmos participantes ao longo dos momentos selecionados. Esta análise usa todos os participantes incluídos com dados completos em todos esses momentos, sem os filtros da agenda ou os grupos da comparação independente.": "screen.59ea14d6e1a7",
  "Prepare ao menos três momentos e uma variável numérica no plano de acompanhamento.": "screen.3a7f18ff40d7",
