  "Aplicar seleção de vários momentos": "screen.a6f355e67fe7",
  "Os resultados abaixo seguem a seleção aplicada, em ordem dos dias previstos. Editar os campos acima exige Aplicar seleção; salvar na conta exige Salvar resultados.": "screen.33fb29e7cde1",
  "fora por visitas ou medidas incompletas. Todas as médias abaixo usam exatamente as mesmas pessoas.": "screen.1700e7917de5",
  "Conferir participantes e dados ausentes": "screen.ff2a23f630e6",
  "Uma pessoa pode ter ausências em vários momentos; as contagens por momento não devem ser somadas para obter o total excluído. Na seleção, primeiro são contadas visitas incompletas, depois medidas vazias em visitas conferidas.": "screen.2bfcfcdca4ad",
  "participantes completos com datas reais invertidas. Confira as visitas; o teste fica bloqueado.": "screen.c825e327feae",
