  "Confira escala, valores extremos, diferenças e datas. Esta lista de códigos não entra nas exportações agregadas.": "screen.fc89b5977c38",
  "Participantes anteriores": "screen.f68448a59198",
  "Próximos participantes": "screen.4efb90505596",
  "ANOVA de medidas repetidas · Greenhouse–Geisser": "screen.a4b428d68da5",
  "Teste global de igualdade das médias dos momentos. Revise normalidade dos contrastes/resíduos, valores extremos, independência entre participantes e mesma escala. A correção de esfericidade é aplicada sempre, sem afirmar que os pressupostos foram testados automaticamente. A análise trata os momentos como categorias; não estima uma tendência por dia nem ajusta os intervalos reais das consultas.": "screen.fa1f43cd3e73",
  "Nesta versão, o número de participantes completos precisa ser maior que o número de momentos; esse limite operacional não garante poder ou adequação. Perdas podem enviesar a análise. Não há pós-testes automáticos, ajuste por covariáveis, método não paramétrico ou modelo misto.": "screen.9fbd2c65aff6",
  "Conferi o vínculo das medidas à mesma pessoa, a escala, a independência entre participantes e a adequação da normalidade dos contrastes/resíduos e dos valores extremos.": "screen.adb31e76ab92",
