  "Combine as sugestões": "screen.b75a7500f0c9",
  "Marque os cartões que se complementam e confira a busca antes de aplicar. Comece pela busca ampla recomendada. Não é necessário selecionar todos: exigir muitos conceitos com AND reduz a recuperação. Uma estratégia completa pode já incluir os conceitos dos outros cartões.": "screen.d05ba0827ccc",
  "Selecionar todas": "screen.2052bbcbe3cf",
