  "sugestão": "screen.2ce596be2817",
  "Como combinar os cartões": "screen.6fa29fc1147b",
  "AND · exigir todos os conceitos": "screen.253fd1f62ef3",
  "OR · aceitar qualquer conceito": "screen.3addaae633bd",
  "AND restringe a busca à presença de todos os conceitos; OR amplia a busca. Termos listados no mesmo cartão são alternativas unidas por OR. Termos sem campo explícito preservam o mapeamento automático do PubMed, sem forçar frases exatas em título/resumo.": "screen.965c6aecff54",
  "Busca combinada editável": "screen.af0752bbff05",
  "caracteres. Aplicar substitui o campo de busca e mantém os filtros de período e tipo de estudo.": "screen.e4105ca523ad",
