  "Intervalo de confiança do efeito": "screen.f6d6bdc29b93",
  "Leia a estimativa, sua incerteza e o contexto do estudo em conjunto. O valor de p não mede importância clínica; associação ou diferença observada não estabelece causa e efeito.": "screen.f0397ede0326",
  "Mudança média · depois menos antes": "screen.bd7669bee82d",
  "Intervalo de confiança de 95% da mudança": "screen.3fc6734ca26a",
  "Aumento ou redução da medida não significa automaticamente melhora. A mudança observada não demonstra que o tratamento a causou.": "screen.a4314d8b4bd5",
  "Momentos comparados": "screen.204a54711c21",
  "Valor de p da comparação global · corrigido": "screen.2c0d38d9d5f1",
  "O teste global não identifica quais momentos diferem nem demonstra uma evolução contínua ou um efeito do tratamento. Confira as médias e as perdas; comparações específicas exigem planejamento próprio.": "screen.6c8f648afe8f",
  "Coeficiente positivo indica valor estimado maior; negativo, menor. Para números, a diferença é por 1 unidade; para categorias, em relação ao grupo de referência. Associação ajustada não estabelece causalidade ou previsão clínica validada.": "screen.ada761080d12",
