  "Registre bases pesquisadas, critérios de elegibilidade, avaliação de qualidade, número de estudos e método de síntese.": "screen.9f188b3153d7",
  "Registre randomização, intervenção, comparador, perdas, desfechos e análise por intenção de tratar.": "screen.1f5ef341fc86",
