  "Registre linha do tempo, achados clínicos, intervenção, evolução, consentimento e aprendizado central.": "screen.cf6e894669a1",
  "Descreva claramente população, desenho, medidas, análise, resultados e limitações.": "screen.95e50a2de9ec",
  "Referências": "screen.7d688deddd40",
  "Use um título de 2 a 160 caracteres e detalhes de até 2.000, sem identificadores pessoais.": "screen.233c622cd0f6",
  "Confira a data da tarefa.": "screen.17960dc2f36c",
  "Origem da sugestão inválida.": "screen.3ee754a382e3",
  "Encerrar seu uso ou sua conta": "screen.55a7165546d2",
  "Você pode deixar de usar a plataforma a qualquer momento. Para excluir a conta e seus dados, solicite atendimento em Contato, escolhendo Privacidade. Antes, exporte os projetos que deseja conservar.": "screen.3fc11c9a6742",
  "Vínculo com um programa": "screen.cbc1eabc91db",
  "O encerramento de seu vínculo institucional e a exclusão de sua conta pessoal são pedidos distintos. Informe qual deseja realizar para que a equipe confirme o procedimento e os dados envolvidos.": "screen.f8ef97c2f064",
  "Planos anuais futuros": "screen.22552560ecf8",
  "Preço final, prazo da licença, forma de pagamento, renovação, cancelamento e regras de reembolso serão informados antes de qualquer contratação. Não há renovação automática nem compra de recargas habilitada agora.": "screen.8988abf42711",
  "Dúvidas sobre cobrança": "screen.2901ad6ba8e4",
  "Se tiver uma dúvida sobre uma cobrança associada ao produto, use Contato e descreva a situação sem informar número completo de cartão, senhas ou dados bancários.": "screen.38f3281809b4",
  "Vagas conforme o tamanho do programa": "screen.5eb00cce7b1b",
  "A quantidade de vagas é configurável: não há obrigação de contratar 30 alunos. O orçamento anual acompanha o número de vagas; a proposta comercial deve ser confirmada antes da contratação.": "screen.1e818ee13b30",
  "Convites e turmas": "screen.e4250911f4d5",
  "A coordenação pode organizar turmas e gerar códigos de convite com validade e limite de usos. O residente entra com sua própria conta e mantém seu espaço individual.": "screen.8498bc95303f",
  "Acompanhamento com privacidade": "screen.d7f90e28b831",
  "O painel institucional mostra participantes, turmas e uso da franquia. O conteúdo dos projetos é acessível em modo de leitura quando o residente autoriza o compartilhamento. Biblioteca e ideias pessoais permanecem privadas.": "screen.28f0019ed035",
  "Franquia e acesso individual": "screen.dfcb796410e1",
  "A estrutura permite distribuir franquia entre participantes e registrar consumo. A venda individual permanece disponível como proposta. IA e pagamento ainda não foram ativados nesta fase.": "screen.59793567318e",
  "Dados de conta e pesquisa": "screen.7ffaf0ed79d4",
  "O Supabase armazena autenticação, perfil, projetos, ideias salvas, referências e matriz de evidências para permitir que você retome o trabalho. Programas institucionais registram participação, convites, licenças e consumo.": "screen.8e70e153e5ec",
  "Radar público e contato": "screen.d38ed6cb3bff",
  "O tema informado é enviado às bases PubMed e Crossref e pode ficar em cache por até uma hora. O controle de tentativas mantém um hash do IP, tipo de consulta, data e contagem; registros antigos são removidos após dois dias, na próxima solicitação. O formulário registra nome, e-mail, assunto e mensagem para atendimento.": "screen.1607378baa0e",
  "Cookies e armazenamento no navegador": "screen.b72195790516",
  "Cookies de autenticação mantêm a sessão. Há armazenamento local de preferências e dados legados. Ao escolher criar conta no Radar demonstrativo, o tema fica neste navegador para você retomá-lo por até sete dias; pode ser descartado no aviso de Meu Espaço. Não ativamos nesta etapa ferramentas de publicidade ou rastreamento de marketing.": "screen.af91c2e73cd5",
  "Infraestrutura e terceiros": "screen.d423152a3788",
  "Usamos Vercel para hospedagem e Supabase para autenticação e banco. Esses fornecedores podem processar dados e registros técnicos fora do Brasil conforme suas configurações e políticas. A IA ainda não recebe conteúdo: não está conectada nesta versão.": "screen.42d8e77d8583",
  "Quem pode acessar": "screen.e472c4b389cf",
  "Projetos, biblioteca e ideias são privados por usuário. Coordenadores recebem dados de participação e consumo e os projetos que você compartilhar. A equipe responsável pela operação possui acesso técnico para manutenção e atendimento; mensagens de contato não são públicas.": "screen.faff12709938",
  "Retenção e seus pedidos": "screen.a93949b7bee6",
  "Os dados da conta são mantidos enquanto ela estiver em uso. Solicite acesso, correção, informações sobre tratamento ou exclusão em Contato, escolhendo Privacidade, sem enviar documentos ou dados sensíveis no primeiro pedido. A equipe verificará sua identidade para atender. Exclusões e retenções necessárias serão explicadas no atendimento.": "screen.b23570c2c4aa",
  "Informações para o lançamento": "screen.6673221ab192",
  "A identificação jurídica e o canal institucional definitivo do responsável serão publicados antes da contratação comercial. Esta página descreve a fase de testes e será atualizada junto com o lançamento pago.": "screen.61e0f61a5d40",
  "Finalidade acadêmica": "screen.cc8baf3687d0",
  "O Scholar apoia organização de pesquisas. Não substitui orientação, revisão científica ou aprovação ética e não oferece aconselhamento clínico. Você deve conferir fontes, métodos e exigências de sua instituição.": "screen.cd341f95fb87",
  "Conta e autoria": "screen.624331a9e21a",
  "Utilize um e-mail acessível, mantenha suas credenciais protegidas e registre apenas conteúdo que possa usar legitimamente. Você é responsável pela autoria, citações e revisão de seus projetos.": "screen.e7be6b1499dd",
  "Dados que não devem ser enviados": "screen.543138b009ca",
  "Não cadastre identificadores de pacientes, prontuários, dados sensíveis ou informações de terceiros sem autorização. Use descrições gerais ou dados anonimizados adequadamente.": "screen.a1f871d845d2",
  "Acesso e disponibilidade": "screen.ef34c093eded",
  "As ferramentas podem mudar durante os testes. Bases externas podem ficar indisponíveis; buscas não garantem cobertura completa. O Radar público tem limite básico por rede e usa resultados em cache.": "screen.7a3d3c0316c9",
  "Compartilhamento institucional": "screen.833fba1937f0",
  "Sua conta pessoal não se torna pública ao entrar em um programa. Os coordenadores acompanham participantes e franquias; só recebem o conteúdo de projetos explicitamente compartilhados.": "screen.99d2c23968fa",
  "Cobrança e contato": "screen.284c1603c36e",
  "Não há checkout nem cobrança automática nesta versão. Valores e franquias apresentados são proposta de lançamento. Dúvidas ou encerramento de conta podem ser solicitados no contato.": "screen.2afac2f0a7ce",
